begin;
create temp table assertions(label text);grant all on assertions to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into assertions values(label);end$$;
insert into auth.users(id,email,is_anonymous) values ('a1000000-0000-4000-8000-000000000001','learning-a@qa.invalid',false),('a1000000-0000-4000-8000-000000000002','learning-b@qa.invalid',false),('a1000000-0000-4000-8000-000000000003',null,true);
create temp table receipt(k text primary key,v jsonb);grant all on receipt to authenticated;
set local role authenticated;set local request.jwt.claims='{"sub":"a1000000-0000-4000-8000-000000000001","is_anonymous":false}';
select public.create_class_with_roster('a2000000-0000-4000-8000-000000000001','7A',7,6,'pilot');
insert into receipt values('set',public.library_action_v2('{"contractVersion":2,"action":"save","id":"a3000000-0000-4000-8000-000000000001","revision":0,"ready":true,"document":{"title":"Bilangan","kind":"cards","items":[{"id":"a4000000-0000-4000-8000-000000000001","kind":"card","prompt":"2+3","options":["5","4","3","2"],"key":"A","explanation":"Lima"},{"id":"a4000000-0000-4000-8000-000000000002","kind":"card","prompt":"3+3","options":["5","6","3","2"],"key":"B","explanation":"Enam"}]},"mapping":{"default":{"topicId":"bilangan","competencyId":"bilangan-operasi","mappingVersion":1},"overrides":[]}}'));
select pg_temp.ok(not (select v?'error' from receipt where k='set'),'v2 ready+mapping stored');
insert into receipt values('run',public.library_action_v2('{"contractVersion":2,"action":"start","id":"a5000000-0000-4000-8000-000000000001","classId":"a2000000-0000-4000-8000-000000000001","collectionId":"a3000000-0000-4000-8000-000000000001","version":1,"date":"2026-10-13","mode":"teach","responseMethod":"cards"}'));
select pg_temp.ok((select v->>'responseMethod'='cards' from receipt where k='run'),'teach cards persists method');
insert into receipt select 'answer',jsonb_build_object('contractVersion',2,'action','response','id',v->'id','formId',v->'formId','version',1,'pageIndex',0,'studentId',v#>'{roster,0,id}','revision',0,'answers',jsonb_build_array('A',null),'answerStates',jsonb_build_array('answered','blank'),'status','review','source','scan') from receipt where k='run';
insert into receipt values('review',public.library_action_v2((select v from receipt where k='answer')));
select pg_temp.ok((select v#>'{responses,0,answers,1}'='null'::jsonb from receipt where k='review'),'blank preserved as null not ?');
select pg_temp.ok((select v#>>'{responses,0,status}'='review' from receipt where k='review'),'unresolved review persists');
select public.library_action_v2((select v from receipt where k='answer'));
select pg_temp.ok((select count(*)=1 from public.library_response_history),'duplicate scan no extra history');
select public.library_action_v2((select v||'{"revision":1,"answers":["A","B"],"answerStates":["answered","answered"],"status":"received","source":"manual"}'::jsonb from receipt where k='answer'));
select pg_temp.ok((select count(*)=2 from public.library_response_history),'correction history preserved');
select pg_temp.ok(public.library_action_v2((select v||'{"revision":0,"answers":["B","B"],"answerStates":["answered","answered"],"status":"received"}' from receipt where k='answer'))->>'error'='CONFLICT','stale correction conflicts');
insert into receipt values('prepare-input','{"action":"prepare","id":"a6000000-0000-4000-8000-000000000001","classId":"a2000000-0000-4000-8000-000000000001","date":"2026-10-13","competency":{"topicId":"bilangan","competencyId":"bilangan-operasi","mappingVersion":1},"absentStudentIds":[],"groupCount":3,"seed":"stable","source":"evidence"}');
insert into receipt values('lesson',public.group_lesson_action((select v from receipt where k='prepare-input')));
select pg_temp.ok(not(select v?'error' from receipt where k='lesson'),'prepare real class');
select pg_temp.ok((select count(*)=1 from receipt,jsonb_array_elements(v->'evidenceSnapshot') e where k='lesson' and e->>'status'='known'),'one accepted child evidence, unknown others');
select pg_temp.ok((select count(*)=6 and count(distinct id)=6 from receipt,jsonb_array_elements(v->'groups') g,jsonb_array_elements_text(g->'studentIds') id where k='lesson'),'present covered once');
select pg_temp.ok(public.group_lesson_action((select v from receipt where k='prepare-input'))=(select v from receipt where k='lesson'),'prepare retry stable');
insert into receipt select 'save-input',jsonb_build_object('action','save','id',v->'id','revision',1,'seed','stable','groupingSource','evidence','groups',v->'groups','assignments',(select jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'groupId',g->'id','method',case when n=1 then 'board' when n=2 then 'cards' else 'teacher' end,'collectionId','a3000000-0000-4000-8000-000000000001','version',1) order by n) from jsonb_array_elements(v->'groups') with ordinality t(g,n))) from receipt where k='lesson';
insert into receipt values('saved',public.group_lesson_action((select v from receipt where k='save-input')));
select pg_temp.ok(not(select v?'error' from receipt where k='saved'),'saved assignment snapshots');
select pg_temp.ok((select count(*)=3 from public.library_runs where prepared),'draft child bindings persisted before start');
select pg_temp.ok((select jsonb_array_length(v->'runs')=0 from (select public.library_action('{"action":"list"}') v) t),'legacy list excludes new teach cards/children');
select pg_temp.ok(public.group_lesson_action((select v from receipt where k='save-input'))->>'error'='CONFLICT','stale draft save rejected');
select pg_temp.ok(public.group_lesson_action((select v||jsonb_build_object('revision',2,'assignments',(select jsonb_agg(a||jsonb_build_object('method','board')) from jsonb_array_elements(v->'assignments') a)) from receipt where k='save-input'))->>'error'='INVALID_INPUT','two simultaneous board assignments rejected');
select pg_temp.ok(public.group_lesson_action((select v||jsonb_build_object('revision',2,'groups',jsonb_set(v->'groups','{1,studentIds}',v#>'{groups,0,studentIds}')) from receipt where k='save-input'))->>'error'='INVALID_INPUT','duplicate/lost roster edit rejected');
select pg_temp.ok(public.library_action_v2((select jsonb_build_object('contractVersion',2,'action','response','id',r.id,'formId',r.form_id,'version',r.version,'pageIndex',0,'studentId',r.roster->0->'id','revision',0,'source','manual','status','received','answers',jsonb_build_array('A','B'),'answerStates',jsonb_build_array('answered','answered')) from public.group_assignments a join public.library_runs r on r.id=a.run_id where a.method='cards'))->>'error'='INVALID_INPUT','draft printable form cannot grade before begin');
insert into receipt values('begun',public.group_lesson_action('{"action":"begin","id":"a6000000-0000-4000-8000-000000000001","revision":2}'));
select pg_temp.ok((select v->>'status'='active' from receipt where k='begun'),'begin active');
select pg_temp.ok((select v->'assignments'->0->'formId'=(select v->'assignments'->0->'formId' from receipt where k='saved') from receipt where k='begun'),'begin retains printed form binding');
insert into receipt values('results',public.learning_results('{"action":"list"}'));
select pg_temp.ok((select jsonb_array_length(v->'entries')=2 from receipt where k='results'),'one root run+lesson, no child duplicate index');
set local request.jwt.claims='{"sub":"a1000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok((select count(*)=0 from public.group_lessons),'cross owner RLS');
select pg_temp.ok(public.group_lesson_action('{"action":"detail","id":"a6000000-0000-4000-8000-000000000001"}')->>'error'='NOT_FOUND','cross owner RPC');
set local request.jwt.claims='{"sub":"a1000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select count(*)=0 from public.library_response_history),'board no private history');
select pg_temp.ok(public.group_lesson_action('{"action":"list"}')->>'error'='FORBIDDEN','board no teacher mutation');
set local request.jwt.claims='{"sub":"a1000000-0000-4000-8000-000000000001","is_anonymous":false}';
insert into receipt values('closed',public.group_lesson_action('{"action":"close","id":"a6000000-0000-4000-8000-000000000001","revision":3}'));
select pg_temp.ok((select v->>'status'='closed' from receipt where k='closed'),'class close independent');
insert into receipt select 'late',jsonb_build_object('contractVersion',2,'action','response','id',r.id,'formId',r.form_id,'version',1,'pageIndex',0,'studentId',r.roster->0->'id','revision',0,'answers',jsonb_build_array('A','B'),'answerStates',jsonb_build_array('answered','answered'),'status','received','source','manual') from public.group_assignments a join public.library_runs r on r.id=a.run_id where a.method='cards';
select public.library_action_v2((select v from receipt where k='late'));
select pg_temp.ok((select count(*)=1 from public.library_responses where run_id=((select v from receipt where k='late')->>'id')::uuid),'late cards accepted');
select pg_temp.ok((select count(*)=3 from public.library_runs where parent_lesson_id is not null and status='closed'),'late card does not resurrect board/child run');
select public.group_lesson_action('{"action":"finalize","id":"a6000000-0000-4000-8000-000000000001","revision":4,"acknowledgeMissing":true}');
select public.library_action_v2((select v||'{"revision":1,"answers":["B","B"]}' from receipt where k='late'));
select pg_temp.ok((select payload->>'assessmentRevision'='2' from public.group_lessons),'late correction advances assessment revision');
select pg_temp.ok((select payload->'groups'=(select v->'groups' from receipt where k='lesson') from public.group_lessons),'correction preserves old group snapshot');
reset role;select count(*)||' group lesson assertions PASS' from assertions;rollback;
